function cheapestWalk(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  const go = (r: number, c: number): number => {
    if (r === R - 1 && c === C - 1) return grid[r][c];
    let best = Infinity;
    if (r + 1 < R) best = Math.min(best, go(r + 1, c));
    if (c + 1 < C) best = Math.min(best, go(r, c + 1));
    return grid[r][c] + best;
  };
  return go(0, 0);
}

