function cheapestWalk(grid: number[][]): number {
  const R = grid.length, C = grid[0].length;
  const best: number[][] = Array.from({ length: R }, () => new Array(C).fill(0));
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < C; c++) {
      if (r === 0 && c === 0) best[r][c] = grid[0][0];
      else if (r === 0) best[r][c] = best[r][c - 1] + grid[r][c];
      else if (c === 0) best[r][c] = best[r - 1][c] + grid[r][c];
      else best[r][c] = grid[r][c] + Math.min(best[r - 1][c], best[r][c - 1]);
    }
  }
  return best[R - 1][C - 1];
}

