function cheapestWalk(grid: number[][]): number {
  const C = grid[0].length;
  const best = new Array(C).fill(0);
  best[0] = grid[0][0];
  for (let c = 1; c < C; c++) best[c] = best[c - 1] + grid[0][c];
  for (let r = 1; r < grid.length; r++) {
    best[0] += grid[r][0];
    // best[c] still holds the row above; best[c - 1] is already this row
    for (let c = 1; c < C; c++) best[c] = grid[r][c] + Math.min(best[c], best[c - 1]);
  }
  return best[C - 1];
}

